import java.util.Scanner;

public class Main {
    public static void main(String[] args) {
        Scanner scanner = new Scanner(System.in);
        long n = scanner.nextLong();
        int x = scanner.nextInt();

        // The sequence of moves has a period of 6
        int m = (int) (n % 6);

        // The permutation after k moves maps initial position -> final position
        int[][] perm = {
            {0, 1, 2}, // 0 moves
            {1, 0, 2}, // 1 move
            {1, 2, 0}, // 2 moves
            {2, 1, 0}, // 3 moves
            {2, 0, 1}, // 4 moves
            {0, 2, 1}  // 5 moves
        };

        // Find initial position i such that perm[m][i] == x
        for (int i = 0; i < 3; i++) {
            if (perm[m][i] == x) {
                System.out.println(i);
                break;
            }
        }
    }
}
